export const clothingData: Record<string, Record<number, ClothingAttributes>> = {};
for (const [type, items] of Object.entries(raw)) {
  clothingData[type] = {};
  for (const [numStr, v] of Object.entries(items)) {
    const num = parseInt(numStr);
    clothingData[type][num] = {
      quality: v[0], strength: v[1], thinness: v[2], topCut: v[3], bra: v[4], panties: v[5],
      pantsShortness: v[6], skirtShortness: v[7], dress: v[8] === 1, onePiece: v[9] === 1, inhibit: v[10],
      coverFront: v[11], coverBack: v[12], coverTop: v[13], style: v[14], style2: v[15], style3: v[16],
      bimbo: v[17] === 1, goth: v[18] === 1, punk: v[19] === 1, prep: v[20] === 1, prude: v[21] === 1,
      prostitute: v[22] === 1, maid: v[23] === 1, server: v[24] === 1, strip: v[25] === 1,
      school: v[26] === 1, office: v[27] === 1, sport: v[28] === 1, swim: v[29] === 1, price: v[30],
    };
  }
}
